To add a "Clear Cart" button and show the total number of items in the cart, we need to modify the existing HTML and JavaScript files. Let's start by editing the HTML file to include the new button and display the total number of items.

### Step 1: Edit the HTML file

We'll add a new button for clearing the cart and a span to display the total number of items.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Paper Harbor</title>
    <style>
        .cart-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
        }
        .cart-item button {
            margin-left: 10px;
        }
        .cart-total {
            margin-top: 20px;
        }
    </style>
</head>
<body>
    <h1>Paper Harbor</h1>
    <div id="catalog">
        <!-- Products will be listed here -->
    </div>
    <div id="cart">
        <h2>Cart</h2>
        <div id="cart-items"></div>
        <div class="cart-total">Total: $<span id="cart-total">0.00</span></div>
        <button id="clear-cart">Clear Cart</button>
    </div>
    <script src="app.js"></script>
</body>
</html>
```

### Step 2: Edit the JavaScript file

We'll add the functionality to clear the cart and update the total number of items.

```javascript
const products = [
    { name: "Pen", price: 1.50, category: "Stationery" },
    { name: "Pencil", price: 0.50, category: "Stationery" },
    { name: "Eraser", price: 0.25, category: "Stationery" },
    { name: "Notebook", price: 2.00, category: "Stationery" },
    { name: "Highlighter", price: 1.00, category: "Stationery" },
    { name: "Stapler", price: 3.00, category: "Office Supplies" }
];

const catalog = document.getElementById('catalog');
const cartItems = document.getElementById('cart-items');
const cartTotal = document.getElementById('cart-total');
const clearCartButton = document.getElementById('clear-cart');

// Function to display products
function displayProducts() {
    products.forEach(product => {
        const productElement = document.createElement('div');
        productElement.className = 'product';
        productElement.innerHTML = `
            <span>${product.name} - $${product.price}</span>
            <button onclick="addToCart('${product.name}', ${product.price})">Add to Cart</button>
        `;
        catalog.appendChild(productElement);
    });
}

// Function to add item to cart
function addToCart(name, price) {
    const itemElement = document.createElement('div');
    itemElement.className = 'cart-item';
    itemElement.innerHTML = `
        <span>${name} - $${price}</span>
        <input type="number" value="1" min="1" onchange="updateCartTotal()">
        <button onclick="removeFromCart(this)">Remove</button>
    `;
    cartItems.appendChild(itemElement);
    updateCartTotal();
}

// Function to remove item from cart
function removeFromCart(button) {
    const itemElement = button.parentElement;
    cartItems.removeChild(itemElement);
    updateCartTotal();
}

// Function to update cart total
function updateCartTotal() {
    let total = 0;
    const cartItems = document.querySelectorAll('.cart-item input');
    cartItems.forEach(input => {
        total += input.value * input.parentElement.querySelector('span').innerText.split(' - $')[1];
    });
    cartTotal.innerText = total.toFixed(2);
}

// Function to clear cart
function clearCart() {
    cartItems.innerHTML = '';
    updateCartTotal();
}

// Display products
displayProducts();

// Add event listener to clear cart button
clearCartButton.addEventListener('click', clearCart);
```

